def classify_tools(tool_defs: list[dict[str, Any]], defer_tools: Optional[frozenset] = None,
                   ) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    """Split a tool-defs list into (visible, deferrable); bridge tools are dropped (re-added
    after classification)."""
    from agent.envoi_request_gate import eager_case_tool
    visible: list[dict[str, Any]] = []
    deferrable: list[dict[str, Any]] = []
    for td, name in zip(tool_defs, _tool_def_names(tool_defs)):
        if name not in BRIDGE_TOOL_NAMES:
            (deferrable if not eager_case_tool(name) and is_deferrable_tool_name(name, defer_tools) else visible).append(td)
    return visible, deferrable

gateway/control_socket.py._envoi_request_gate_status:
def _envoi_request_gate_status(self, params: dict, peer_subject: str) -> dict:
        from agent.envoi_request_gate import runtime_status, RequestGateRefused
        if not peer_subject or self.ticket_store is None or set(params) != {'instance_id','challenge'} or params['instance_id'] != self.ticket_store.instance_id:
            raise RequestGateRefused('PROVIDER_GATE_ATTESTATION_REFUSED')
        return runtime_status(self.ticket_store.instance_id, params['challenge'])
